"use client";

import { useEffect, useMemo, useState } from "react";
import { QRCodeSVG } from "qrcode.react";
import { questions, sleRounds } from "@/lib/quiz-data";
import { generateClassCode, timeLeftFor } from "@/utils/game-logic";
import { Trash2 } from "lucide-react";

type Phase = "lobby" | "question" | "sle" | "leaderboard";
type Player = { id: string; name: string; score: number; joinedAt: number };
type Answer = { id: string; player_id: string; choice: number; correct: boolean };
type GameState = {
  id: string;
  code: string;
  phase: Phase;
  current_question: number;
  revealed: boolean;
  pending_sle_index: number | null;
  question_started_at: number;
  question_count: number;
};

const letters = ["A", "B", "C", "D"];
const confettiColors = ["#6366f1", "#14b8a6", "#f97316", "#ef4444", "#facc15", "#3b82f6"];

export default function HostPage() {
  const [game, setGame] = useState<GameState | null>(null);
  const [players, setPlayers] = useState<Player[]>([]);
  const [answers, setAnswers] = useState<Answer[]>([]);
  const [confetti, setConfetti] = useState<number[]>([]);
  const [showQR, setShowQR] = useState(false);
  const [joinUrl, setJoinUrl] = useState("");
  const [timeLeft, setTimeLeft] = useState(25);
  const [hostAuth, setHostAuth] = useState(false);
  const [password, setPassword] = useState("");

  const supabase = createClient();

  const question = game ? questions[game.current_question] : null;
  const sle = game ? sleRounds[game.pending_sle_index ?? 0] : sleRounds[0];
  const rankedPlayers = useMemo(
    () => [...players].sort((a, b) => b.score - a.score),
    [players]
  );

  useEffect(() => {
    setJoinUrl(window.location.origin);
    initializeGame();
  }, []);

  async function initializeGame() {
    const code = generateClassCode();
    const { data, error } = await supabase.from('games').insert({
      code,
      phase: 'lobby',
      current_question: 0,
      revealed: false,
      pending_sle_index: null,
      question_started_at: Date.now(),
      question_count: questions.length
    } as any).select().single();

    if (data) {
      setGame(data as GameState);
      setPlayers([]);
      setAnswers([]);
    }
  }

  // Real-time subscriptions
  useEffect(() => {
    if (!game) return;

    const channel = supabase
      .channel(`host-${game.id}`)
      .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'players', filter: `game_id=eq.${game.id}` }, (payload: any) => {
        setPlayers(prev => [...prev, { id: payload.new.id, name: payload.new.name, score: payload.new.score, joinedAt: payload.new.joined_at }]);
      })
      .on('postgres_changes', { event: 'UPDATE', schema: 'public', table: 'players', filter: `game_id=eq.${game.id}` }, (payload: any) => {
        setPlayers(prev => prev.map(p => p.id === payload.new.id ? { ...p, score: payload.new.score } : p));
      })
      .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'answers', filter: `game_id=eq.${game.id}` }, (payload: any) => {
        setAnswers(prev => [...prev, payload.new as Answer]);
      })
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [game?.id]);

  // Timer loop
  useEffect(() => {
    if (!game || game.phase !== 'question' || game.revealed) return;
    const id = setInterval(() => {
      const left = timeLeftFor(game.phase, game.question_started_at);
      setTimeLeft(left);
      if (left <= 0) {
        hostAction('reveal');
      }
    }, 500);
    return () => clearInterval(id);
  }, [game?.phase, game?.revealed, game?.question_started_at]);

  async function hostAction(action: "start" | "reveal" | "next" | "reset") {
    if (!game) return;

    if (action === "reset") {
      await initializeGame();
      return;
    }

    const updates: Partial<GameState> = {};

    if (action === "start") {
      updates.phase = 'question';
      updates.current_question = 0;
      updates.revealed = false;
      updates.question_started_at = Date.now();
      // Reset scores in DB
      players.forEach(p => supabase.from('players').update({ score: 0 } as any).eq('id', p.id).then());
      setAnswers([]);
    }

    if (action === "reveal") {
      updates.revealed = true;
      // Calculate scores
      const q = questions[game.current_question];
      answers.forEach(ans => {
        if (ans.correct) {
          const player = players.find(p => p.id === ans.player_id);
          if (player) {
            // Give points based on time left when they answered, but since we don't store answer time, give a flat amount + bonus
            const newScore = player.score + 600 + (timeLeft * 20);
            supabase.from('players').update({ score: newScore } as any).eq('id', player.id).then();
          }
        }
      });
    }

    if (action === "next") {
      const q = questions[game.current_question];
      const atRoundEnd = q.questionIndex === sleRounds[q.roundIndex].questions.length - 1;

      if (game.phase === 'sle') {
        if (game.current_question >= questions.length - 1) {
          updates.phase = 'leaderboard';
          launchConfetti();
        } else {
          updates.phase = 'question';
          updates.current_question = game.current_question + 1;
          updates.revealed = false;
          updates.question_started_at = Date.now();
          setAnswers([]);
        }
      } else {
        if (atRoundEnd) {
          updates.phase = 'sle';
          updates.pending_sle_index = q.roundIndex;
        } else if (game.current_question >= questions.length - 1) {
          updates.phase = 'leaderboard';
          launchConfetti();
        } else {
          updates.phase = 'question';
          updates.current_question = game.current_question + 1;
          updates.revealed = false;
          updates.question_started_at = Date.now();
          setAnswers([]);
        }
      }
    }

    const { data } = await supabase.from('games').update(updates as any).eq('id', game.id).select().single();
    if (data) {
      setGame(data as GameState);
    }
  }

  async function kickPlayer(id: string, name: string) {
    if (window.confirm(`Are you sure you want to remove ${name} from the game?`)) {
      await supabase.from('players').delete().eq('id', id);
      setPlayers(prev => prev.filter(p => p.id !== id));
    }
  }

  function launchConfetti() {
    setConfetti(Array.from({ length: 100 }, (_, i) => i));
    window.setTimeout(() => setConfetti([]), 6000);
  }

  useEffect(() => {
    function shortcuts(event: KeyboardEvent) {
      if (!game) return;
      if (event.code === "Space" && game.phase === "question") {
        event.preventDefault();
        hostAction(game.revealed ? "next" : "reveal");
      }
    }
    window.addEventListener("keydown", shortcuts);
    return () => window.removeEventListener("keydown", shortcuts);
  }, [game]);

  if (!hostAuth) {
    return (
      <main className="app">
        <section className="card" style={{ maxWidth: '400px', width: '100%', margin: 'auto' }}>
          <div className="join-wrapper">
            <div className="stack stack-sm text-center">
              <h1>Host Access</h1>
              <p className="subtitle">Enter the host password to continue.</p>
            </div>
            <div className="join-form">
              <div className="input-group">
                <input
                  type="password"
                  className="input-field"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  onKeyDown={(e) => e.key === "Enter" && password === "cwb" && setHostAuth(true)}
                  placeholder="Password"
                  autoFocus
                />
              </div>
              <button 
                className="btn btn-primary btn-full btn-lg" 
                onClick={() => password === "cwb" && setHostAuth(true)}
              >
                Enter
              </button>
              {password !== "" && password !== "cwb" && <div className="message error">Incorrect password</div>}
            </div>
          </div>
        </section>
      </main>
    );
  }

  if (!game) {
    return (
      <main className="app host-app">
        <div className="spinner" />
      </main>
    );
  }

  return (
    <main className="app host-app">

      {/* ── LOBBY ── */}
      {game.phase === "lobby" && (
        <section className="card host-lobby">
          <div className="topbar">
            <div className="badge">Host Control Panel</div>
            <button className="btn btn-ghost" onClick={() => hostAction("reset")}>
              Reset
            </button>
          </div>

          <div className="lobby-header">
            <h1>How Well Do You Know Aadit?</h1>
            <p className="subtitle">
              Students join on their devices. Show this screen on the projector.
            </p>
          </div>

          {/* Toggle: Code vs QR */}
          <div className="toggle-group center-x">
            <button
              className={`toggle-btn ${!showQR ? "active" : ""}`}
              onClick={() => setShowQR(false)}
            >
              Class Code
            </button>
            <button
              className={`toggle-btn ${showQR ? "active" : ""}`}
              onClick={() => setShowQR(true)}
            >
              QR Code
            </button>
          </div>

          <div className="code-display">
            {!showQR ? (
              <>
                <div className="text-muted text-sm" style={{ fontWeight: 700, textTransform: "uppercase", letterSpacing: "0.08em" }}>
                  Class Code
                </div>
                <div className="code-value">{game.code}</div>
              </>
            ) : (
              <>
                <div className="text-muted text-sm" style={{ fontWeight: 700, textTransform: "uppercase", letterSpacing: "0.08em" }}>
                  Scan to Join
                </div>
                {joinUrl && (
                  <div className="qr-wrapper">
                    <QRCodeSVG
                      value={joinUrl}
                      size={200}
                      bgColor="#ffffff"
                      fgColor="#0f0f11"
                      level="M"
                    />
                  </div>
                )}
                <div className="text-muted text-xs">{joinUrl}</div>
              </>
            )}
            <div className="badge green">{players.length} player{players.length !== 1 ? "s" : ""} joined</div>
          </div>

          {/* Player chips */}
          {players.length > 0 && (
            <div className="player-chips">
              {players.map((p) => (
                <div className="player-chip" key={p.id} style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                  <span>{p.name}</span>
                  <button 
                    onClick={() => kickPlayer(p.id, p.name)}
                    style={{ background: 'transparent', border: 'none', color: '#ef4444', cursor: 'pointer', display: 'flex', alignItems: 'center' }}
                    title="Remove Player"
                  >
                    <Trash2 size={16} />
                  </button>
                </div>
              ))}
            </div>
          )}

          <div className="button-row">
            <button
              className="btn btn-primary btn-lg"
              onClick={() => hostAction("start")}
              disabled={players.length === 0}
            >
              Start Quiz →
            </button>
          </div>
        </section>
      )}

      {/* ── QUESTION ── */}
      {game.phase === "question" && question && (
        <section className="card question-card">
          <div className="topbar">
            <div className="badge">{question.round}</div>
            <div className="badge">Q{game.current_question + 1} / {game.question_count}</div>
            <div className={`timer ${timeLeft <= 5 && !game.revealed ? "urgent" : ""}`}>
              {game.revealed ? "✓" : `${timeLeft}s`}
            </div>
          </div>

          <div className="question-box">
            <h2>{question.text}</h2>
          </div>

          <div className="host-answers">
            {question.answers.map((ans, index) => (
              <div
                className={`host-answer ${letters[index].toLowerCase()} ${game.revealed && index === question.correct ? "correct" : ""} ${game.revealed && index !== question.correct ? "dim" : ""}`}
                key={ans}
              >
                <span className="letter-badge">{letters[index]}</span>
                <span>{ans}</span>
              </div>
            ))}
          </div>

          <div className="stats-row">
            <div className="stat-box">
              <div className="stat-value">{answers.length}</div>
              <div className="stat-label">Answered</div>
            </div>
            <div className="stat-box">
              <div className="stat-value">{players.length}</div>
              <div className="stat-label">Players</div>
            </div>
            <div className="stat-box">
              <div className="stat-value">+1000</div>
              <div className="stat-label">Max Pts</div>
            </div>
          </div>

          {game.revealed && <div className="story-box">{question.story}</div>}

          <div className="button-row">
            {!game.revealed && (
              <button className="btn btn-primary btn-lg" onClick={() => hostAction("reveal")}>
                Reveal Answer
              </button>
            )}
            {game.revealed && (
              <button className="btn btn-primary btn-lg" onClick={() => hostAction("next")}>
                Next →
              </button>
            )}
          </div>
        </section>
      )}

      {/* ── SLE REVEAL ── */}
      {game.phase === "sle" && (
        <section className="card">
          <div className="sle-reveal">
            <div className="badge accent">SLE Reveal</div>
            <div className="sle-title-badge">{sle.title}</div>

            <div className="sle-notes">
              <div className="sle-note">
                <b>Definition</b>
                {sle.definition}
              </div>
              <div className="sle-note">
                <b>My Claim</b>
                {sle.claim}
              </div>
              <div className="sle-note">
                <b>My Evidence</b>
                {sle.evidence}
              </div>
            </div>

            <button className="btn btn-primary btn-lg" onClick={() => hostAction("next")}>
              Continue Quiz →
            </button>
          </div>
        </section>
      )}

      {/* ── LEADERBOARD ── */}
      {game.phase === "leaderboard" && (
        <section className="card">
          <div className="sle-reveal">
            <div className="badge green">Game Over</div>
            <h1>Final Leaderboard</h1>

            <div className="leaderboard">
              {rankedPlayers.slice(0, 3).map((p, i) => (
                <div className="rank-row" key={p.id}>
                  <span className="rank-num">#{i + 1}</span>
                  <span className="rank-name">{p.name}</span>
                  <span className="rank-score">{p.score}</span>
                </div>
              ))}
            </div>

            <button className="btn btn-primary btn-lg" onClick={() => hostAction("reset")}>
              Play Again
            </button>
          </div>
        </section>
      )}

      {/* ── CONFETTI ── */}
      <div className="confetti" aria-hidden="true">
        {confetti.map((piece) => (
          <i
            key={piece}
            style={{
              left: `${Math.random() * 100}%`,
              background: confettiColors[piece % confettiColors.length],
              animationDuration: `${2.4 + Math.random() * 2.8}s`,
              animationDelay: `${Math.random() * 0.8}s`
            }}
          />
        ))}
      </div>
    </main>
  );
}
